+    var(--g-color-base-background);
+}
+
+.login-card {
+  box-sizing: border-box;
+  width: min(100%, 440px);
+  padding: clamp(var(--g-spacing-5), 7vw, var(--g-spacing-8));
+  border: 1px solid var(--g-color-line-generic);
+  border-radius: var(--g-border-radius-2xl);
