+  letter-spacing: 0.12em;
+}
+
+.login-title {
+  margin: 0;
+  font-size: clamp(28px, 6vw, 34px);
+  font-weight: 600;
+  letter-spacing: -0.035em;
+  line-height: 1.2;
+}
+
+.login-description {
+  margin: var(--g-spacing-2) 0 0;
+  color: var(--g-color-text-secondary);
+  font-size: 15px;
+  line-height: 1.5;
+}
+
+.login-form {
+  display: flex;
+  flex-direction: column;
+  gap: var(--g-spacing-4);
+  margin-top: var(--g-spacing-7);
+}
+
+.form-field {
+  display: flex;
+  flex-direction: column;
+  gap: var(--g-spacing-2);
+}
+
+.field-label {
+  color: var(--g-color-text-primary);
+  font-size: 14px;
+  font-weight: 500;
+}
+
+.login-footnote {
+  margin: var(--g-spacing-6) 0 0;
+  color: var(--g-color-text-hint);
+  font-size: 12px;
+  text-align: center;
 }
